ALTER TABLE monitor_event_actions ADD CONSTRAINT monitor_actions_business_time_check CHECK (business_time IS NULL OR (jsonb_typeof(business_time) = 'object' AND CASE business_time->>'kind' WHEN 'instant' THEN jsonb_typeof(business_time->'at') = 'string' WHEN 'deadline' THEN jsonb_typeof(business_time->'at') = 'string' WHEN 'date' THEN jsonb_typeof(business_time->'date') = 'string' AND jsonb_typeof(business_time->'timeZone') = 'string' WHEN 'range' THEN jsonb_typeof(business_time->'from') = 'string' AND jsonb_typeof(business_time->'through') = 'string' ELSE false END) IS TRUE) NOT VALID;
